def probeRoot = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/preparation/loop-direct-t-probe-20261106')
def probeClasses = new File(probeRoot, 'compiled/probe')
def prefixOverlay = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/preparation/packet-prefix-rollback-capsule-20261105/compiled/overlay')
def capsuleReceipt = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/preparation/packet-prefix-rollback-capsule-20261105/capsule-receipt.json')
allprojects { p ->
    if (p.name == 'opentaint-dataflow' && p.projectDir.name == 'opentaint-dataflow') {
        p.afterEvaluate {
            def probe = p.sourceSets.create('loopDirectTProbe')
            probe.java.setSrcDirs([])
            probe.resources.setSrcDirs([])
            p.kotlin.sourceSets.getByName('loopDirectTProbe').kotlin.setSrcDirs([new File(probeRoot, 'src')])
            probe.compileClasspath = p.sourceSets.main.output + p.sourceSets.test.output + p.configurations.testCompileClasspath
            probe.output.classesDirs.setFrom(probeClasses)
            p.tasks.named('compileLoopDirectTProbeKotlin') {
                dependsOn p.tasks.named('testClasses')
                destinationDirectory.set(probeClasses)
                compilerOptions.jvmTarget.set(p.tasks.named('compileKotlin').get().compilerOptions.jvmTarget)
                compilerOptions.freeCompilerArgs.add('-Xfriend-paths=' + [
                    p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile,
                    p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile,
                ].collect { it.absolutePath }.join(','))
            }
            ['Current', 'PrefixOff'].each { variant ->
                p.tasks.register('runLoopDirectT' + variant + 'Probe', JavaExec) {
                    dependsOn p.tasks.named('compileLoopDirectTProbeKotlin')
                    def off = variant == 'PrefixOff'
                    classpath = (off ? p.files(prefixOverlay, probeClasses) : p.files(probeClasses)) + p.sourceSets.test.runtimeClasspath
                    mainClass.set('org.opentaint.dataflow.bidi.diagnostics.LoopDirectTProbe')
                    jvmArgs '-Xmx1g', '-XX:ActiveProcessorCount=1'
                    args off ? 'proper-prefix-off' : 'current', off ? prefixOverlay.absolutePath :
                        '/drive-testcomp/opentaint-go-rules/opentaint-w3/core/opentaint-dataflow-core/opentaint-dataflow/build/classes/kotlin/main'
                    doFirst {
                        def expected = off ? prefixOverlay.canonicalPath : probeClasses.canonicalPath
                        def paths = classpath.files.collect { it.canonicalPath }
                        if (paths[0] != expected) throw new GradleException('Unexpected first classpath entry')
                        if (paths.any { it.contains('normal-star-rollback-capsule') || it.contains('inside-star-rollback-capsule') ||
                            it.contains('prefix-canonical-rollback-capsule') || it.contains('same-point-rollback-capsule') })
                            throw new GradleException('Unselected overlay present')
                        if (off) {
                            def receipt = new groovy.json.JsonSlurper().parse(capsuleReceipt)
                            if (receipt.status != 'PASS') throw new GradleException('B capsule not verified')
                            receipt.emittedFiles.each { pin ->
                                def file = new File(pin.path)
                                if (java.security.MessageDigest.getInstance('SHA-256').digest(file.bytes).encodeHex().toString() != pin.sha256)
                                    throw new GradleException('B overlay changed: ' + pin.path)
                            }
                        }
                        new File(probeRoot, off ? 'prefix-off-classpath.txt' : 'current-classpath.txt').text = paths.join('\n') + '\n'
                    }
                }
            }
        }
    }
}

