// Capture only existing diagnostic hooks. No analysis or fixture settings change.
def traceDir = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/preparation/loop-direct-t-native-f3-trace-20261106')
def pins = new groovy.json.JsonSlurper().parse(new File(traceDir, 'provider-pins.json'))
gradle.projectsEvaluated {
  allprojects { p ->
    p.tasks.matching { it.name == 'runLoopDirectTCurrentProbe' }.configureEach {
      // Appended provider leaves the original probe and native class origins first.
      classpath = classpath + p.files(pins.jars.collect { new File(it.path) })
      systemProperty 'org.opentaint.bidi.loopTraceMethod', 'Loop direct T observer root [context]'
      systemProperty 'org.opentaint.bidi.loopTraceRun', '3'
      systemProperty 'org.opentaint.bidi.loopTraceLimit', '4096'
      systemProperty 'logback.configurationFile', new File(traceDir, 'logback.xml').absolutePath
      doFirst {
        pins.jars.each { pin ->
          def jar = new File(pin.path)
          def actual = java.security.MessageDigest.getInstance('SHA-256').digest(jar.bytes).encodeHex().toString()
          if (actual != pin.sha256) throw new GradleException('Diagnostic provider changed: ' + pin.path)
        }
        new File(traceDir, 'trace-classpath.txt').text = classpath.files.collect { it.canonicalPath }.join('\n') + '\n'
        println('NATIVE_F3_TRACE_CAPTURE method=Loop direct T observer root [context] run=3 limit=4096 provider=logback-1.3.16 diagnosticOnly=true')
      }
    }
  }
}

